    def optimize(v, scales, loss):
        cache = [None, None, None]

        def parts(u):
            if cache[0] is None or not np.array_equal(cache[0], u[:2]):
                cache[:] = [u[:2].copy(), *design(decode(u))]
            return cache[1:]

